/// <summary>
/// PaffH 27.12.23
/// fill conUpdate, if valueOld != valueNew
/// </summary>
/// <returns>int</returns>
public int fillConUpdate()
{
    int i, nPosOld, nPosNew;
    int bis;
    int nOffset;
    //anytype valueOld, valueNew;
    str     valueOld, valueNew;
    ;
    conUpdate   = connull();
    bis = conLen(conProtInfo) ? real2int(conlen(conProtInfo) / NDXKBVBuildingProject2RicoKalkProtConstants::conRecLen) : 0;
    for (i = 1; i <= bis; i++)
    {
        //valueOld    = null;
        //valueNew    = null;
        nOffset = ((i-1) * NDXKBVBuildingProject2RicoKalkProtConstants::conRecLen);
        nPosOld     = nOffset + NDXKBVBuildingProject2RicoKalkProtConstants::containerElement_ValueOldStr;
        nPosNew     = nOffset + NDXKBVBuildingProject2RicoKalkProtConstants::containerElement_ValueNewStr;
        // Ist der Wert zu speichern?
        valueOld = conpeek(conProtInfo, nPosOld);
        valueNew = conpeek(conProtInfo, nPosNew);
        if (valueOld != valueNew)
        {
            conUpdate += conpeek(conProtInfo, nOffset + NDXKBVBuildingProject2RicoKalkProtConstants::containerElement_Type);
            conUpdate += conpeek(conProtInfo, nOffset + NDXKBVBuildingProject2RicoKalkProtConstants::containerElement_ValueOld);
            conUpdate += conpeek(conProtInfo, nOffset + NDXKBVBuildingProject2RicoKalkProtConstants::containerElement_ValueNew);
            conUpdate += conpeek(conProtInfo, nOffset + NDXKBVBuildingProject2RicoKalkProtConstants::containerElement_ValueOldStr);
            conUpdate += conpeek(conProtInfo, nOffset + NDXKBVBuildingProject2RicoKalkProtConstants::containerElement_ValueNewStr);
            conUpdate += conpeek(conProtInfo, nOffset + NDXKBVBuildingProject2RicoKalkProtConstants::containerElement_ADOFieldName);
        }
    }
    lconUpdateFilled = true;

    return conlen(conUpdate) ? real2int(conlen(conUpdate) / NDXKBVBuildingProject2RicoKalkProtConstants::conRecLen) : 0;
}

