    bis = conLen(conUpdate) ? real2int(conlen(conUpdate) / NDXKBVBuildingProject2RicoKalkProtConstants::conRecLen) : 0;
    for (i = 1; i <= bis; i++)
    {
        nOffset = ((i-1) * NDXKBVBuildingProject2RicoKalkProtConstants::conRecLen);
