public str getMappedRicoKalkUser(RefRecId _hcmWorkerRefRecId)
{
    HcmPersonnelNumberId personnelNumber = HcmWorker::find(_hcmWorkerRefRecId).PersonnelNumber;
    str userid = personnelNumber;
    NDXRICOUserMap nDXRICOUserMap = NDXRICOUserMap::findAXUser(personnelNumber);
    if (nDXRICOUserMap)
    {
        userid = nDXRICOUserMap.UserIDRICO;
    }
    return userid;
}

