            _kalkBVKopf.addSqlFieldWithValueInt(NDXRicoKalkTblKalkBVKopfConstants::BVNR_Niedax, _valueNew);
            break;
        default :
            throw error(strFmt("@NDXBase:NDXFieldIsNotTakenIntoAccountYet", _type));
    }
}
